-- FUNC06 - Saude, Atencao Basica e Regulacao. Corretiva, aditiva e idempotente.
create schema if not exists sigov;

alter table sigov.saude_unidade add column if not exists cnes varchar(20), add column if not exists telefone varchar(30), add column if not exists email varchar(254);
alter table sigov.saude_paciente add column if not exists cpf varchar(11), add column if not exists telefone varchar(30), add column if not exists email varchar(254), add column if not exists responsavel_nome varchar(250), add column if not exists observacao_clinica_protegida text;
alter table sigov.saude_profissional add column if not exists cpf varchar(11), add column if not exists conselho varchar(30), add column if not exists numero_conselho varchar(40), add column if not exists cbo varchar(20), add column if not exists especialidade varchar(120), add column if not exists carga_horaria numeric(6,2), add column if not exists unidade_principal_id bigint;
alter table sigov.saude_agenda add column if not exists duracao_minutos integer, add column if not exists capacidade integer not null default 1, add column if not exists motivo_cancelamento text;
alter table sigov.saude_atendimento add column if not exists agenda_id bigint, add column if not exists acolhimento_id bigint, add column if not exists inicio_at timestamptz, add column if not exists fim_at timestamptz, add column if not exists motivo_cancelamento text;
alter table sigov.saude_vacinacao add column if not exists lote varchar(80), add column if not exists fabricante varchar(120), add column if not exists validade date, add column if not exists dose varchar(40), add column if not exists motivo_duplicidade text, add column if not exists motivo_cancelamento text;

create table if not exists sigov.saude_paciente_responsavel (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,paciente_id bigint not null,nome varchar(250) not null,documento varchar(30),parentesco varchar(80),telefone varchar(30),ativo boolean not null default true,is_deleted boolean not null default false,created_at timestamptz not null default now(),created_by bigint);
create table if not exists sigov.saude_equipe (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,unidade_id bigint not null,nome varchar(180) not null,tipo varchar(30) not null,status varchar(20) not null default 'ATIVA',is_deleted boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz,created_by bigint,updated_by bigint,constraint ck_saude_equipe_tipo check(tipo in('ESF','NASF','SAUDE_BUCAL','OUTRA')),constraint ck_saude_equipe_status check(status in('ATIVA','INATIVA')));
create table if not exists sigov.saude_equipe_profissional (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,equipe_id bigint not null,profissional_id bigint not null,vigencia_inicio date not null,vigencia_fim date,created_at timestamptz not null default now(),created_by bigint,constraint ck_saude_equipe_prof_vigencia check(vigencia_fim is null or vigencia_fim>=vigencia_inicio));
create table if not exists sigov.saude_acolhimento (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,paciente_id bigint not null,unidade_id bigint not null,profissional_id bigint,data_hora timestamptz not null default now(),queixa_principal text not null,pressao_arterial varchar(20),temperatura numeric(4,1),peso numeric(7,2),altura numeric(4,2),frequencia_cardiaca integer,saturacao numeric(5,2),classificacao_risco varchar(20),status varchar(20) not null default 'ABERTO',motivo_cancelamento text,is_deleted boolean not null default false,created_at timestamptz not null default now(),created_by bigint,updated_at timestamptz,updated_by bigint,constraint ck_saude_acolhimento_risco check(classificacao_risco is null or classificacao_risco in('AZUL','VERDE','AMARELO','LARANJA','VERMELHO')),constraint ck_saude_acolhimento_status check(status in('ABERTO','ENCAMINHADO','FINALIZADO','CANCELADO')),constraint ck_saude_acolhimento_final check(status<>'FINALIZADO' or classificacao_risco is not null));
create table if not exists sigov.saude_prontuario_evolucao (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,atendimento_id bigint not null,subjetivo text,objetivo text,avaliacao text,plano text,diagnostico text,cid varchar(20),procedimento text,prescricao text,orientacoes text,finalizado boolean not null default false,retifica_evolucao_id bigint,justificativa_retificacao text,created_at timestamptz not null default now(),created_by bigint,updated_at timestamptz,updated_by bigint);
create table if not exists sigov.saude_medicamento (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,nome varchar(250) not null,apresentacao varchar(180) not null,unidade varchar(30) not null,controle_especial boolean not null default false,material_id bigint,ativo boolean not null default true,is_deleted boolean not null default false,created_at timestamptz not null default now(),created_by bigint);
create table if not exists sigov.saude_dispensacao (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,paciente_id bigint not null,medicamento_id bigint not null,quantidade numeric(16,3) not null,unidade_id bigint not null,profissional_id bigint not null,data_hora timestamptz not null default now(),lote varchar(80),validade date,origem_estoque_id bigint,justificativa text,observacao text,created_at timestamptz not null default now(),created_by bigint,constraint ck_saude_dispensacao_quantidade check(quantidade>0));
create table if not exists sigov.saude_encaminhamento (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,paciente_id bigint not null,atendimento_origem_id bigint,unidade_origem_id bigint not null,servico varchar(250) not null,prioridade varchar(20) not null,status varchar(20) not null default 'SOLICITADO',justificativa_clinica text not null,unidade_destino_id bigint,profissional_destino_id bigint,data_agendada timestamptz,justificativa_status text,is_deleted boolean not null default false,created_at timestamptz not null default now(),created_by bigint,updated_at timestamptz,updated_by bigint,constraint ck_saude_enc_prioridade check(prioridade in('BAIXA','NORMAL','ALTA','URGENTE')),constraint ck_saude_enc_status check(status in('SOLICITADO','EM_ANALISE','AGENDADO','ATENDIDO','DEVOLVIDO','CANCELADO')),constraint ck_saude_enc_devolucao check(status<>'DEVOLVIDO' or nullif(trim(justificativa_status),'') is not null),constraint ck_saude_enc_agenda check(status<>'AGENDADO' or (unidade_destino_id is not null and profissional_destino_id is not null and data_agendada is not null)));
create table if not exists sigov.saude_historico_status (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,recurso varchar(40) not null,recurso_id bigint not null,status_anterior varchar(30),status_novo varchar(30) not null,justificativa text,created_at timestamptz not null default now(),created_by bigint);
create table if not exists sigov.saude_auditoria (id bigint generated by default as identity primary key,tenant_id bigint not null,entidade_id bigint not null,recurso varchar(60) not null,recurso_id bigint,acao varchar(40) not null,antes jsonb,depois jsonb,finalidade_acesso varchar(250),dados_sensiveis boolean not null default false,usuario_id bigint,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create unique index if not exists ux_saude_unidade_cnes on sigov.saude_unidade(tenant_id,entidade_id,cnes) where cnes is not null and trim(cnes)<>'' and not is_deleted;
create unique index if not exists ux_saude_paciente_cpf on sigov.saude_paciente(tenant_id,entidade_id,cpf) where cpf is not null and trim(cpf)<>'' and not is_deleted;
create unique index if not exists ux_saude_paciente_cns_func06 on sigov.saude_paciente(tenant_id,entidade_id,cns) where cns is not null and trim(cns)<>'' and not is_deleted;
create unique index if not exists ux_saude_agenda_prof_horario on sigov.saude_agenda(tenant_id,entidade_id,profissional_id,data_inicio) where profissional_id is not null and status<>'CANCELADO' and not is_deleted;
create unique index if not exists ux_saude_vacinacao_dose_data on sigov.saude_vacinacao(tenant_id,entidade_id,paciente_id,nome,dose,data_referencia) where status='APLICADA' and coalesce(motivo_duplicidade,'')='';
create index if not exists ix_saude_acolhimento_painel on sigov.saude_acolhimento(tenant_id,entidade_id,status,classificacao_risco,data_hora);
create index if not exists ix_saude_equipe_profissional_vigencia on sigov.saude_equipe_profissional(tenant_id,entidade_id,equipe_id,profissional_id,vigencia_inicio);
create index if not exists ix_saude_prontuario_atendimento on sigov.saude_prontuario_evolucao(tenant_id,entidade_id,atendimento_id,created_at);
create index if not exists ix_saude_dispensacao_historico on sigov.saude_dispensacao(tenant_id,entidade_id,paciente_id,data_hora);
create index if not exists ix_saude_encaminhamento_painel on sigov.saude_encaminhamento(tenant_id,entidade_id,status,prioridade,created_at);
create index if not exists ix_saude_historico_status_recurso on sigov.saude_historico_status(tenant_id,entidade_id,recurso,recurso_id,created_at);
create index if not exists ix_saude_auditoria_recurso on sigov.saude_auditoria(tenant_id,entidade_id,recurso,recurso_id,created_at);

do $$ begin
 if not exists(select 1 from pg_constraint where conname='ck_saude_agenda_capacidade_func06') then alter table sigov.saude_agenda add constraint ck_saude_agenda_capacidade_func06 check(capacidade>0 and (duracao_minutos is null or duracao_minutos>0)); end if;
 if not exists(select 1 from pg_constraint where conname='ck_saude_profissional_carga_func06') then alter table sigov.saude_profissional add constraint ck_saude_profissional_carga_func06 check(carga_horaria is null or carga_horaria>0); end if;
end $$;

create or replace function sigov.fn_func06_validar_operacao() returns trigger language plpgsql as $$
declare v_status text; v_ativo boolean; v_integrado boolean; v_saldo numeric;
begin
 if tg_table_name='saude_agenda' then select status into v_status from sigov.saude_unidade where id=new.unidade_id and not is_deleted; if v_status not in('ATIVA','ATIVO') then raise exception 'Unidade inativa nao recebe agenda'; end if; select status into v_status from sigov.saude_profissional where id=new.profissional_id and not is_deleted; if v_status<>'ATIVO' then raise exception 'Profissional inativo ou afastado nao recebe agenda'; end if; if new.status='CANCELADO' and nullif(trim(new.motivo_cancelamento),'') is null then raise exception 'Cancelamento exige motivo'; end if; end if;
 if tg_table_name='saude_atendimento' then select status into v_status from sigov.saude_unidade where id=new.unidade_id and not is_deleted; if tg_op='INSERT' and v_status not in('ATIVA','ATIVO') then raise exception 'Unidade inativa nao recebe atendimento'; end if; if new.status='CANCELADO' and nullif(trim(new.motivo_cancelamento),'') is null then raise exception 'Cancelamento exige justificativa'; end if; end if;
 if tg_table_name='saude_prontuario_evolucao' and tg_op='UPDATE' and old.finalizado and new.retifica_evolucao_id is null then raise exception 'Prontuario finalizado exige retificacao auditada'; end if;
 if tg_table_name='saude_vacinacao' then if new.status='APLICADA' and new.validade<new.data_referencia::date then raise exception 'Lote vencido nao pode ser aplicado'; end if; if new.status='CANCELADA' and nullif(trim(new.motivo_cancelamento),'') is null then raise exception 'Cancelamento exige justificativa'; end if; end if;
 if tg_table_name='saude_dispensacao' then select ativo,material_id is not null into v_ativo,v_integrado from sigov.saude_medicamento where id=new.medicamento_id and tenant_id=new.tenant_id and entidade_id=new.entidade_id and not is_deleted; if v_ativo is not true then raise exception 'Medicamento inativo'; end if; if v_integrado then select coalesce(sum(quantidade),0) into v_saldo from sigov.almoxarifado_estoque where material_id=(select material_id from sigov.saude_medicamento where id=new.medicamento_id) and tenant_id=new.tenant_id and entidade_id=new.entidade_id; if v_saldo<new.quantidade then raise exception 'Saldo insuficiente no Almoxarifado'; end if; end if; end if;
 return new;
end $$;
drop trigger if exists trg_func06_agenda on sigov.saude_agenda; create trigger trg_func06_agenda before insert or update on sigov.saude_agenda for each row execute function sigov.fn_func06_validar_operacao();
drop trigger if exists trg_func06_atendimento on sigov.saude_atendimento; create trigger trg_func06_atendimento before insert or update on sigov.saude_atendimento for each row execute function sigov.fn_func06_validar_operacao();
drop trigger if exists trg_func06_prontuario on sigov.saude_prontuario_evolucao; create trigger trg_func06_prontuario before update on sigov.saude_prontuario_evolucao for each row execute function sigov.fn_func06_validar_operacao();
drop trigger if exists trg_func06_vacinacao on sigov.saude_vacinacao; create trigger trg_func06_vacinacao before insert or update on sigov.saude_vacinacao for each row execute function sigov.fn_func06_validar_operacao();
drop trigger if exists trg_func06_dispensacao on sigov.saude_dispensacao; create trigger trg_func06_dispensacao before insert or update on sigov.saude_dispensacao for each row execute function sigov.fn_func06_validar_operacao();

insert into sigov.permissao(modulo,chave,recurso,acao,descricao,ativo,is_deleted) select 'saude',v.chave,v.recurso,v.acao,'Permissao FUNC06',true,false from(values
('saude.dashboard.visualizar','saude.dashboard','visualizar'),('saude.unidade.visualizar','saude.unidade','visualizar'),('saude.unidade.criar','saude.unidade','criar'),('saude.unidade.editar','saude.unidade','editar'),('saude.paciente.visualizar','saude.paciente','visualizar'),('saude.paciente.criar','saude.paciente','criar'),('saude.paciente.editar','saude.paciente','editar'),('saude.profissional.visualizar','saude.profissional','visualizar'),('saude.profissional.criar','saude.profissional','criar'),('saude.profissional.editar','saude.profissional','editar'),('saude.agenda.visualizar','saude.agenda','visualizar'),('saude.agenda.criar','saude.agenda','criar'),('saude.agenda.cancelar','saude.agenda','cancelar'),('saude.acolhimento.visualizar','saude.acolhimento','visualizar'),('saude.acolhimento.criar','saude.acolhimento','criar'),('saude.atendimento.visualizar','saude.atendimento','visualizar'),('saude.atendimento.criar','saude.atendimento','criar'),('saude.atendimento.finalizar','saude.atendimento','finalizar'),('saude.prontuario.visualizar','saude.prontuario','visualizar'),('saude.prontuario.retificar','saude.prontuario','retificar'),('saude.vacinacao.visualizar','saude.vacinacao','visualizar'),('saude.vacinacao.aplicar','saude.vacinacao','aplicar'),('saude.farmacia.visualizar','saude.farmacia','visualizar'),('saude.farmacia.dispensar','saude.farmacia','dispensar'),('saude.regulacao.visualizar','saude.regulacao','visualizar'),('saude.regulacao.criar','saude.regulacao','criar'),('saude.exportar','saude','exportar'))v(chave,recurso,acao) where not exists(select 1 from sigov.permissao p where p.chave=v.chave);
insert into sigov.perfil_permissao(perfil_acesso_id,permissao_id,efeito,ativo,is_deleted) select pa.id,p.id,'PERMITIR',true,false from sigov.perfil_acesso pa cross join sigov.permissao p where pa.codigo_externo='SUPERADMIN' and pa.sistemico and pa.ativo and not pa.is_deleted and p.modulo='saude' and p.ativo and not p.is_deleted on conflict(perfil_acesso_id,permissao_id) do update set efeito='PERMITIR',ativo=true,is_deleted=false;
